def eras(periods, names):
  for p, e in zip(periods, names): p["era"] = e
  return periods

def osm_only(mid, frm, key, way, he, fr, en, ru, conf, h=9):
  """Église présente dans OpenStreetMap mais absente de la brochure : nom et confession seulement."""
  return dict(id=mid, **{"from": frm, "to": 5}, certainty="attested", name=L(he, fr, en, ru),
    text=L(f"{he} — {conf[0]}. מופיעה במפה (OpenStreetMap); אין עליה פרק בחוברת הקורס.", f"{fr} — {conf[1]}. Présente sur la carte (OpenStreetMap) ; la brochure du cours n’en parle pas.",
           f"{en} — {conf[2]}. On the map (OpenStreetMap); the course booklet does not cover it.", f"{ru} — {conf[3]}. Есть на карте (OpenStreetMap); в брошюре курса не описана."),
    shape={"type": "church", "osm": key, "h": h}, placementNote=SCHEM, sources=[osm(way)], osmOnly=True)

